package org.diy.liferecorder;
import java.util.*;import org.json.*;
/** File-local clustering with duration-weighted centers, conservative identity and explicit uncertainty. */
final class SpeakerMatcher {
 static final double MATCH=.60,STRONG=.68,JOIN=.60,MERGE=.66,COHERENCE=.52;
 static float[] normalize(float[] vector){double norm=0;for(float x:vector){if(!Float.isFinite(x))throw new IllegalArgumentException("声纹无效");norm+=x*x;}if(norm<1e-12)throw new IllegalArgumentException("声纹无效");float[] out=vector.clone();for(int i=0;i<out.length;i++)out[i]/=Math.sqrt(norm);return out;}
 static final class Profile {
  final ArrayList<float[]> templates=new ArrayList<>();final float[] center;final int samples,anchors;
  Profile(JSONObject json){JSONArray values=json.optJSONArray("templates");if(values==null){values=new JSONArray();values.put(json.optJSONArray("embedding"));}int dimension=0;for(int i=0;i<values.length();i++){JSONArray row=values.optJSONArray(i);if(row==null||row.length()<16)continue;float[] v=new float[row.length()];for(int j=0;j<v.length;j++)v[j]=(float)row.optDouble(j);v=normalize(v);if(dimension>0&&dimension!=v.length)throw new IllegalArgumentException("声纹维度不一致");dimension=v.length;templates.add(v);}if(templates.isEmpty())throw new IllegalArgumentException("声纹无效");float[] sum=new float[dimension];for(float[] v:templates)for(int i=0;i<sum.length;i++)sum[i]+=v[i];center=normalize(sum);samples=json.optInt("samples",1);anchors=Math.min(10,Math.max(1,json.optInt("anchor_count",templates.size())));}
  double score(float[] vector){double first=-1,second=-1;for(float[] v:templates){double s=OfflineSpeech.cosine(v,vector);if(s>first){second=first;first=s;}else second=Math.max(second,s);}double nearest=second<0?first:(first+second)/2;return Math.max(OfflineSpeech.cosine(center,vector),nearest);}
 }
 static final class Observation {final int segment;final float[] vector;final long speechMs;Observation(int index,float[] v,long ms){segment=index;vector=normalize(v);speechMs=ms;}}
 private static final class Group {
  final ArrayList<Observation> members=new ArrayList<>();float[] center;long speechMs;
  Group(Observation o){add(o);}void add(Observation o){members.add(o);recenter();}
  void recenter(){float[] sum=new float[members.get(0).vector.length];speechMs=0;for(Observation o:members){double weight=Math.min(6000,o.speechMs)/1000.0;speechMs+=o.speechMs;for(int i=0;i<sum.length;i++)sum[i]+=o.vector[i]*weight;}center=normalize(sum);}
  double minimum(float[] vector){double score=1;for(Observation o:members)score=Math.min(score,OfflineSpeech.cosine(o.vector,vector));return score;}
 }
 static void assign(JSONArray segments,List<Observation> observations,Profile mine)throws Exception{
  ArrayList<Group> groups=new ArrayList<>();for(Observation o:observations){if(o.speechMs<2400)continue;Group best=null;double score=JOIN;for(Group g:groups){double similarity=OfflineSpeech.cosine(o.vector,g.center);if(similarity>=score&&g.minimum(o.vector)>=COHERENCE){best=g;score=similarity;}}if(best==null)groups.add(new Group(o));else best.add(o);}
  boolean merged;do{merged=false;outer:for(int a=0;a<groups.size();a++)for(int b=a+1;b<groups.size();b++){Group x=groups.get(a),y=groups.get(b);if(OfflineSpeech.cosine(x.center,y.center)<MERGE)continue;boolean compatible=true;for(Observation o:y.members)if(x.minimum(o.vector)<COHERENCE){compatible=false;break;}if(compatible){x.members.addAll(y.members);x.recenter();groups.remove(b);merged=true;break outer;}}}while(merged);
  int anonymous=0;for(Group g:groups){int number=0;double groupSelf=mine==null?-1:mine.score(g.center);for(Observation o:g.members){JSONObject segment=segments.getJSONObject(o.segment);if(segment.optBoolean("speaker_confirmed"))continue;double self=mine==null?-1:mine.score(o.vector),membership=OfflineSpeech.cosine(o.vector,g.center),other=-1;for(Group rival:groups)if(rival!=g)other=Math.max(other,OfflineSpeech.cosine(o.vector,rival.center));boolean me=mine!=null&&(self>=STRONG||(self>=MATCH&&membership>=JOIN)||(groupSelf>=.65&&self>=.50&&membership>=.68));boolean ambiguous=membership-other<.08&&self<STRONG;segment.put("voice_similarity",self).put("speaker_group_similarity",membership).put("speaker_method","duration-weighted-centroid-v2");if(me&&!ambiguous)segment.put("speaker","可能是我").put("speaker_confidence","candidate");else if(!ambiguous&&(g.members.size()>=2||g.speechMs>=6000)){if(number==0)number=++anonymous;segment.put("speaker","说话人 "+number).put("speaker_confidence","file-local-group");}else segment.put("speaker","身份不确定").put("speaker_confidence","insufficient-evidence");}}
 }
 static JSONObject profile(List<float[]> fresh,Profile previous,boolean append,String version)throws Exception{ArrayList<float[]> values=new ArrayList<>();if(append&&previous!=null)values.addAll(previous.templates);for(float[] v:fresh)values.add(normalize(v));int anchors=append&&previous!=null?previous.anchors:Math.min(10,values.size());while(values.size()>12)values.remove(anchors);JSONArray templates=new JSONArray();for(float[] v:values){JSONArray row=new JSONArray();for(float x:v)row.put(x);templates.put(row);}JSONObject result=new JSONObject().put("model_version",version).put("templates",templates).put("samples",append&&previous!=null?Math.min(12,previous.samples+1):1).put("profile_version",2).put("anchor_count",anchors);Profile p=new Profile(result);JSONArray center=new JSONArray();for(float x:p.center)center.put(x);return result.put("embedding",center);}
}
